import{_ as a,o as r,c as t,ag as s}from"./chunks/framework.Ccn6roXv.js";const h=JSON.parse('{"title":"1. Web framework basics","description":"The minimum web framework concepts needed before looking at TanStack Start server functions.","frontmatter":{"title":"1. Web framework basics","description":"The minimum web framework concepts needed before looking at TanStack Start server functions."},"headers":[],"relativePath":"guide/01-web-framework-basics.md","filePath":"guide/01-web-framework-basics.md"}'),o={name:"guide/01-web-framework-basics.md"};function i(n,e,l,c,d,p){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="web-framework-basics" tabindex="-1">Web framework basics <a class="header-anchor" href="#web-framework-basics" aria-label="Permalink to &quot;Web framework basics&quot;">​</a></h1><p>A web framework helps developers build an application that runs partly in the browser and partly on a server.</p><p>The browser handles user interaction. The server handles trusted work such as reading databases, checking sessions, and calling private services.</p><h2 id="request-and-response" tabindex="-1">Request and response <a class="header-anchor" href="#request-and-response" aria-label="Permalink to &quot;Request and response&quot;">​</a></h2><p>Every web feature eventually becomes a request and a response.</p><p>The browser sends:</p><ul><li>A method, such as <code>GET</code> or <code>POST</code></li><li>A path, such as <code>/login</code></li><li>Headers, such as cookies and content type</li><li>An optional body</li></ul><p>The server returns:</p><ul><li>A status code</li><li>Headers</li><li>A body</li></ul><p>Security starts here. Every value sent by the browser is attacker-controlled unless the server proves otherwise.</p><h2 id="routing" tabindex="-1">Routing <a class="header-anchor" href="#routing" aria-label="Permalink to &quot;Routing&quot;">​</a></h2><p>A route maps a request path to code.</p><p>Traditional APIs often expose routes like this:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/profile</span></span></code></pre></div><p>Modern full-stack frameworks may hide this behind generated client code. The browser still sends HTTP. The server still receives a request.</p><h2 id="client-code-and-server-code" tabindex="-1">Client code and server code <a class="header-anchor" href="#client-code-and-server-code" aria-label="Permalink to &quot;Client code and server code&quot;">​</a></h2><p>Client code runs in the browser. Users can inspect it, modify requests, and replay traffic.</p><p>Server code runs on infrastructure controlled by the application owner. It can keep secrets and enforce authorization.</p><p>The main security rule is simple: client code may improve user experience, but server code must enforce trust.</p><h2 id="security-property" tabindex="-1">Security property <a class="header-anchor" href="#security-property" aria-label="Permalink to &quot;Security property&quot;">​</a></h2><p>The property to preserve is a clear boundary:</p><ul><li>Browser input is untrusted.</li><li>Server state is trusted only after authentication and authorization.</li><li>Parsed request data is not automatically safe.</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p>Next, learn what TanStack Start adds to this normal web model.</p>',24)])])}const b=a(o,[["render",i]]);export{h as __pageData,b as default};
